// sift-ai: note summaries, weekly digests and Chat comments ("Let them talk") with Claude. Deploy: supabase functions deploy sift-ai
// Secrets: SIFT_ANTHROPIC_API_KEY (Sift's own key), else ANTHROPIC_API_KEY (supabase secrets set). SUPABASE_URL / SUPABASE_ANON_KEY are provided by Supabase.
// It reads notes as the signed-in user (row-level security applies), never sends vault notes, and writes nothing:
// the app saves the results through its normal sync.
import Anthropic from 'npm:@anthropic-ai/sdk@0.133.0';
import { createClient } from 'npm:@supabase/supabase-js@2.117.2';

// ---- lib.ts ----
// Prompts, batching and output checks for the sift-ai function. No imports, so the app's tests can run it in Node.

export const MODEL = 'claude-opus-5-5';
/** Per call: at most this many notes, and batches of at most this many characters per model request. */
export const MAX_IDS = 25, MAX_DIGEST_IDS = 120, BATCH_CHARS = 60_000;

export interface NoteRow { id: string; title: string; body: string; topic: string; lang: string | null; created_at: string; }
export interface Summary { id: string; summary: string; summary_orig: string | null; }

/** Groups notes so each model request stays under BATCH_CHARS. A single longer note goes alone, whole. */
export function batches<T extends { title: string; body: string }>(notes: T[], max = BATCH_CHARS): T[][] {
  const out: T[][] = []; let cur: T[] = [], size = 0;
  for (const n of notes) {
    const len = n.title.length + n.body.length + 80;
    if (cur.length && size + len > max) { out.push(cur); cur = []; size = 0; }
    cur.push(n); size += len;
  }
  if (cur.length) out.push(cur);
  return out;
}

export const SUMMARY_SYSTEM = `You write one-line summaries for a person's private notes app. The notes are theirs: quick captures, lists, reflections, work references, often in English, Japanese or Marathi.

For each note, write:
- summary: one plain English sentence of at most 25 words that says what the note is for or about, so they recognise it at a glance in a list. Keep names, numbers and part numbers that identify it. No preamble such as "This note".
- summary_orig: when the note is mainly written in a language other than English, the same summary in that language; otherwise null.

A note that is only a title or a few words still gets a summary; restate it plainly rather than inventing detail.`;

export const SUMMARY_SCHEMA = {
  type: 'object',
  properties: { summaries: { type: 'array', items: { type: 'object',
    properties: { id: { type: 'string' }, summary: { type: 'string' }, summary_orig: { type: ['string', 'null'] } },
    required: ['id', 'summary', 'summary_orig'], additionalProperties: false } } },
  required: ['summaries'], additionalProperties: false,
} as const;

export const summaryInput = (notes: NoteRow[]) =>
  'Summarise each of these notes. Return one entry per note, with its id unchanged.\n\n' +
  notes.map(n => `<note id="${n.id}">\n<title>${n.title}</title>\n<body>\n${n.body}\n</body>\n</note>`).join('\n\n');

/** Keeps only well-formed summaries for notes that were asked about; trims and drops empty ones. */
export function checkSummaries(raw: unknown, asked: Set<string>): Summary[] {
  const list = (raw as { summaries?: unknown })?.summaries; if (!Array.isArray(list)) return [];
  const seen = new Set<string>(); const out: Summary[] = [];
  for (const s of list as Record<string, unknown>[]) {
    const id = typeof s?.id === 'string' ? s.id : ''; const summary = typeof s?.summary === 'string' ? s.summary.trim() : '';
    if (!asked.has(id) || seen.has(id) || !summary) continue; seen.add(id);
    const orig = typeof s.summary_orig === 'string' && s.summary_orig.trim() ? s.summary_orig.trim() : null;
    out.push({ id, summary, summary_orig: orig });
  }
  return out;
}

export const DIGEST_SYSTEM = `You write the weekly digest at the top of a person's private notes app: a short paragraph that tells them what their week of notes was about.

Write 2 to 4 sentences, at most 80 words, in plain English, addressed to them as "you". Name the main threads and anything that looks unfinished or worth coming back to. Be specific to the notes; no generic encouragement, no lists, no headings, no quotation of whole notes. Reply with the paragraph only.`;

/** The user's topic names by id (custom topics have ids like u_ab12cd). Anything malformed is dropped. */
export type TopicNames = Record<string, string>;
export function checkTopicNames(x: unknown): TopicNames {
  if (!x || typeof x !== 'object' || Array.isArray(x)) return {};
  return Object.fromEntries(Object.entries(x as Record<string, unknown>).filter(([k, v]) => /^[a-z0-9_]{1,12}$/.test(k) && typeof v === 'string' && v.trim() && v.length <= 40).slice(0, 16).map(([k, v]) => [k, (v as string).trim().replace(/["<>]/g, '')]));
}
const topicAttr = (id: string, names: TopicNames) => `topic="${id}"` + (names[id] ? ` topic_name="${names[id]}"` : '');

export const digestInput = (weekOf: string, notes: NoteRow[], names: TopicNames = {}) =>
  `The week starting ${weekOf}. ${notes.length} note${notes.length === 1 ? '' : 's'}, oldest first:\n\n` +
  notes.map(n => `<note date="${n.created_at.slice(0, 10)}" ${topicAttr(n.topic, names)}>\n<title>${n.title}</title>\n<body>\n${n.body}\n</body>\n</note>`).join('\n\n');

export const isWeekOf = (s: unknown): s is string => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
export const isIdList = (x: unknown, max = MAX_IDS): x is string[] => Array.isArray(x) && x.length > 0 && x.length <= max && x.every(i => typeof i === 'string' && /^[0-9a-f-]{36}$/i.test(i));

// "Let them talk": topics comment on each other's notes in the Chat view.
export const MAX_TALK_IDS = 40;
/** The built-in voices. Career is left out: it is the vault topic, so it must never seem to know anything. */
export const TALKERS: Record<string, { name: string; voice: string }> = {
  eng: { name: 'Engineering at work', voice: 'precise and practical, thinks in specs, part numbers and deadlines' },
  soft: { name: 'Building software', voice: 'a builder who wants to ship, spots the app idea in anything' },
  lang: { name: 'Language learning', voice: 'curious about words, now and then drops a Japanese or Marathi word with its meaning' },
  refl: { name: 'Reflections', voice: 'slower and thoughtful, asks what something means for the person' },
  scrap: { name: 'Scraps', voice: 'quick and playful, the friend who remembers odd fragments' },
};
export interface Comment { note_id: string; topic: string; text: string; }
/** Topics the person added have ids like u_ab12cd; only those join the built-ins, so Career (or any other id) can never be smuggled in. */
const CUSTOM_ID = /^u_[a-z0-9]{1,10}$/;

/** The person's descriptions of their own topics, by id. Anything malformed is dropped. */
export function checkTopicAbout(x: unknown): TopicNames {
  if (!x || typeof x !== 'object' || Array.isArray(x)) return {};
  return Object.fromEntries(Object.entries(x as Record<string, unknown>).filter(([k, v]) => CUSTOM_ID.test(k) && typeof v === 'string' && v.trim() && v.length <= 140).slice(0, 16).map(([k, v]) => [k, (v as string).replace(/\s+/g, ' ').trim().replace(/["<>]/g, '')]));
}

/** Who may comment on this request, id → how they sound: the built-ins (under the person's names for them) and the person's own topics. Never Career. */
export function talkers(names: TopicNames = {}, about: TopicNames = {}): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [id, t] of Object.entries(TALKERS)) out[id] = `${names[id] ?? t.name}: ${t.voice}`;
  for (const [id, name] of Object.entries(names)) if (CUSTOM_ID.test(id)) out[id] = `${name}: the person's own topic${about[id] ? ` (${about[id].replace(/[.\s]+$/, '')})` : ''}; speaks as someone who cares about it, in a voice of its own`;
  return out;
}

export const talkSystem = (who: Record<string, string>) => `Sift shows a person's notes as a group chat: each note is a message from its topic. You write a few short comments in which one topic reacts to another topic's note, to make the chat feel alive and to surface connections the person may have missed.

The topics who can comment (by id), and how each sounds:
${Object.entries(who).map(([id, d]) => `- ${id}: ${d}`).join('\n')}

Rules:
- Comment only where it adds something: a link to another note in the list (name it by its title), a question worth asking, a nudge about something unfinished, or a light joke grounded in the notes.
- Never comment on a note from the same topic, and never invent facts beyond the notes.
- Each comment is one or two sentences, at most 25 words, in English, warm and specific. No advice lectures, no hashtags, no emoji spam (one at most).
- Spread comments across different notes and topics. Write about one comment per four notes, at most 10.`;

export const talkSchema = (who: Record<string, string>) => ({
  type: 'object',
  properties: { comments: { type: 'array', items: { type: 'object',
    properties: { note_id: { type: 'string' }, topic: { type: 'string', enum: Object.keys(who) }, text: { type: 'string' } },
    required: ['note_id', 'topic', 'text'], additionalProperties: false } } },
  required: ['comments'], additionalProperties: false,
});

export const talkInput = (notes: NoteRow[], names: TopicNames = {}) => 'The chat, oldest first:\n\n' +
  notes.map(n => `<note id="${n.id}" ${topicAttr(n.topic, names)} date="${n.created_at.slice(0, 10)}">\n<title>${n.title}</title>\n<body>\n${n.body}\n</body>\n</note>`).join('\n\n');

/** Keeps the newest notes that fit in `max` characters (whole notes only, never cut). */
export function newestThatFit<T extends { title: string; body: string }>(notes: T[], max = BATCH_CHARS): T[] {
  const out: T[] = []; let size = 0;
  for (let i = notes.length - 1; i >= 0; i--) { const len = notes[i].title.length + notes[i].body.length + 100; if (out.length && size + len > max) break; out.unshift(notes[i]); size += len; }
  return out;
}

/** Valid comments only: on a note that was sent, by a known talker other than the note's own topic, short, one per note+topic, at most 10. */
export function checkComments(raw: unknown, notes: { id: string; topic: string }[], who: Record<string, string> = talkers()): Comment[] {
  const list = (raw as { comments?: unknown })?.comments; if (!Array.isArray(list)) return [];
  const topicOf = new Map(notes.map(n => [n.id, n.topic])); const seen = new Set<string>(); const out: Comment[] = [];
  for (const c of list as Record<string, unknown>[]) {
    const note_id = typeof c?.note_id === 'string' ? c.note_id : '', topic = typeof c?.topic === 'string' ? c.topic : '';
    const text = typeof c?.text === 'string' ? c.text.replace(/\s+/g, ' ').trim() : '';
    if (!topicOf.has(note_id) || !Object.hasOwn(who, topic) || topic === 'career' || topicOf.get(note_id) === topic || !text || text.length > 220 || seen.has(note_id + topic)) continue;
    seen.add(note_id + topic); out.push({ note_id, topic, text }); if (out.length === 10) break;
  }
  return out;
}

// ---- index.ts ----

// Secrets are shared by every function in the project: Sift prefers its own key, so other apps' ANTHROPIC_API_KEY is left alone.
const apiKey = Deno.env.get('SIFT_ANTHROPIC_API_KEY') || Deno.env.get('ANTHROPIC_API_KEY');
const anthropic = new Anthropic({ apiKey });
const CORS = { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type', 'Access-Control-Allow-Methods': 'POST, OPTIONS' };
const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });

/** One request with server-side fallback: if Claude Opus 5.5's safeguards decline, the API retries on its recommended model. */
async function ask(system: string, input: string, effort: 'low' | 'medium', schema?: Record<string, unknown>) {
  const res = await anthropic.beta.messages.create({
    model: MODEL, max_tokens: 16000, betas: ['server-side-fallback-2026-07-01'], fallbacks: 'default',
    system, messages: [{ role: 'user', content: input }],
    output_config: { effort, ...(schema ? { format: { type: 'json_schema' as const, schema } } : {}) },
  });
  if (res.stop_reason === 'refusal') throw new Error('Claude declined this request.');
  if (res.stop_reason === 'max_tokens') throw new Error('The reply was cut off. Try fewer notes at once.');
  return res.content.filter(b => b.type === 'text').map(b => b.text).join('').trim();
}

Deno.serve(async req => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
  if (req.method !== 'POST') return json({ error: 'POST only' }, 405);
  const sb = createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_ANON_KEY')!, { global: { headers: { Authorization: req.headers.get('Authorization') ?? '' } } });
  const { data: { user } } = await sb.auth.getUser();
  if (!user) return json({ error: 'Sign in first.' }, 401);
  // The project is shared with Weekly Focus: only people with a role there may spend the API key.
  const role = await sb.from('authentication_mode_user_roles').select('role').eq('auth_user_id', user.id).maybeSingle();
  if (!role.data) return json({ error: 'Your account has no Sift role.' }, 403);

  let body: { action?: string; ids?: unknown; week_of?: unknown; topics?: unknown; topic_about?: unknown };
  try { body = await req.json(); } catch { return json({ error: 'Bad JSON' }, 400); }
  const max = body.action === 'digest' ? MAX_DIGEST_IDS : body.action === 'talk' ? MAX_TALK_IDS : MAX_IDS;
  if (!isIdList(body.ids, max)) return json({ error: `ids: 1 to ${max} note ids` }, 400);
  const rows = await sb.from('sift_notes').select('id,title,body,topic,lang,created_at')
    .in('id', body.ids).eq('user_id', user.id).eq('vault', false).is('deleted_at', null).order('created_at');
  if (rows.error) return json({ error: rows.error.message }, 500);
  const notes = (rows.data ?? []) as NoteRow[];
  const names = checkTopicNames(body.topics); // the user's own topic names, for the prompts
  const found = new Set(notes.map(n => n.id)); const skipped = body.ids.filter(id => !found.has(id)); // vault, deleted or not synced yet

  if (!apiKey) return json({ error: 'No Anthropic API key: add the secret SIFT_ANTHROPIC_API_KEY in Supabase (Edge Functions → Secrets).' }, 500);
  try {
    if (body.action === 'summarize') {
      const out: Summary[] = [];
      for (const group of batches(notes)) {
        const text = await ask(SUMMARY_SYSTEM, summaryInput(group), 'low', SUMMARY_SCHEMA);
        out.push(...checkSummaries(JSON.parse(text), new Set(group.map(n => n.id))));
      }
      return json({ summaries: out, skipped });
    }
    if (body.action === 'digest') {
      if (!isWeekOf(body.week_of)) return json({ error: 'week_of: YYYY-MM-DD' }, 400);
      if (!notes.length) return json({ error: 'No notes to write about (vault notes are left out).' }, 400);
      return json({ text: await ask(DIGEST_SYSTEM, digestInput(body.week_of, notes, names), 'medium'), skipped });
    }
    if (body.action === 'talk') {
      // Career is the vault topic: never sent (the vault filter above already drops it, this is belt and braces).
      const chat = newestThatFit(notes.filter(n => n.topic !== 'career'));
      if (chat.length < 2) return json({ error: 'Need at least two notes for the topics to talk about.' }, 400);
      const who = talkers(names, checkTopicAbout(body.topic_about)); // the built-ins and the person's own topics, never Career
      const text = await ask(talkSystem(who), talkInput(chat, names), 'medium', talkSchema(who));
      return json({ comments: checkComments(JSON.parse(text), chat, who), skipped });
    }
    return json({ error: 'action: summarize, digest or talk' }, 400);
  } catch (e) {
    if (e instanceof Anthropic.RateLimitError) return json({ error: 'Claude is busy. Try again in a minute.' }, 429);
    if (e instanceof Anthropic.AuthenticationError) return json({ error: 'The Anthropic API key is wrong or expired. Check the SIFT_ANTHROPIC_API_KEY secret in Supabase.' }, 500);
    if (e instanceof Anthropic.APIError) return json({ error: `Claude API error ${e.status}: ${e.message}` }, 502);
    return json({ error: (e as Error).message }, 500);
  }
});
